/*
 * Builds deploy/: the whole app as three files to paste into the Apps Script editor
 * (Code.gs, Index.html, appsscript.json) instead of the eleven in apps-script/.
 * Usage: node tools/bundle.js      (run after any change to apps-script/)
 */
'use strict';
const fs = require('fs');
const path = require('path');
const vm = require('vm');

const ROOT = path.join(__dirname, '..');
const SRC = path.join(ROOT, 'apps-script');
const OUT = path.join(ROOT, 'deploy');
const read = (f) => fs.readFileSync(path.join(SRC, f), 'utf8');
const ORDER = ['Config.gs', 'Rules.gs', 'Db.gs', 'Auth.gs', 'Api.gs', 'Setup.gs', 'Code.gs'];
const version = /version: '([^']+)'/.exec(read('Config.gs'))[1];

// Code.gs: every server file in order. The page is one plain file here, so doGet serves it
// directly instead of evaluating a template with includes.
let code = '/* Q-TRACK ' + version + ' — bundled server code. Generated by tools/bundle.js from apps-script/*.gs; do not edit by hand. */\n\n'
  + ORDER.map((f) => '/* ===== ' + f + ' ===== */\n' + read(f).trim() + '\n').join('\n');
const tmpl = "HtmlService.createTemplateFromFile('Index')\n    .evaluate()";
if (code.split(tmpl).length !== 2) throw new Error('doGet template call not found exactly once');
code = code.replace(tmpl, () => "HtmlService.createHtmlOutputFromFile('Index')");
new vm.Script(code, { filename: 'Code.gs' });

// Index.html: styles and client script inlined.
const html = read('Index.html')
  .replace("<?!= include('Styles'); ?>", () => read('Styles.html').trim())
  .replace("<?!= include('App'); ?>", () => read('App.html').trim());
if (/<\?/.test(html)) throw new Error('Unresolved template tag in bundled Index.html');
const scripts = html.match(/<script>[\s\S]*?<\/script>/g) || [];
if (scripts.length !== 1) throw new Error('Expected one script block, found ' + scripts.length);
new vm.Script(scripts[0].replace(/^<script>|<\/script>$/g, ''), { filename: 'Index.html' });

fs.mkdirSync(OUT, { recursive: true });
fs.writeFileSync(path.join(OUT, 'Code.gs'), code);
fs.writeFileSync(path.join(OUT, 'Index.html'), html);
fs.copyFileSync(path.join(SRC, 'appsscript.json'), path.join(OUT, 'appsscript.json'));
console.log('deploy/Code.gs ' + Math.round(code.length / 1024) + ' KB, deploy/Index.html ' + Math.round(html.length / 1024) + ' KB, deploy/appsscript.json');
